        /// <summary>
        ///   <para>
        ///     Mutual exclusion function to lock the DSP engine (which runs asynchronously in another thread), so that
        ///     it will not execute.
        ///   </para>
        ///   <para>
        ///     If the DSP engine is already executing, this function is blocked until it has completed.
        ///   </para>
        ///   <para>
        ///     The function may be used to synchronize DSP graph operations carried out by your code. For example, you
        ///     could use this to construct a DSP sub-graph without the DSP engine executing in the background while the
        ///     sub-graph is still under construction.
        ///   </para>
        ///   <para>
        ///     Once you no longer need the DSP engine to be locked, it can be unlocked with System::unlockDSP.
        ///   </para>
        ///   <para>
        ///     Note that if the DSP engine is locked for a significant amount of time, it may result in audible
        ///     skipping or stuttering.
        ///   </para>
        ///   <para>
        ///     <see href="https://www.fmod.com/docs/2.03/api/core-api-system.html#system_lockdsp">System::lockDSP</see>
        ///   </para>
        /// </summary>
        public static Result TryLockDsp(this FmodSystem system) => PInvoke.SystemLockDsp(system);

        /// <summary>
